    int num_blocks = N * num_groups_i;
    // Dynamic shared memory: only2 * num_warps floats (much smaller than before)
    size_t smem_bytes = 2 * num_warps * sizeof(float);

    groupnorm_kernel<<<num_blocks, bsz, smem_bytes>>>(
        pooled.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, Ho, Wo,
        num_groups_i, (float)eps);

